import ifcopenshell
import os

path = '/home/sffc348/Repos/cobbie/acc/bim_models/ac20/arc.ifc'
model = ifcopenshell.open(path)
model_dir = os.path.dirname(path)

# Read Space Usage CSV
csv_path = os.path.join(model_dir, 'Space Usage.csv')
print("Space Usage.csv content:")
with open(csv_path, 'r', encoding='utf-8-sig') as f:
    for i, line in enumerate(f):
        if i < 30:
            print(f"  {line.strip()}")

# Check if spaces have property sets with classification
print("\nChecking space property sets...")
spaces = model.by_type('IfcSpace')
for i, space in enumerate(spaces[:3]):
    print(f"\nSpace: {space.Name} / {space.LongName}")
    print(f"  IsDefinedBy:")
    if hasattr(space, 'IsDefinedBy'):
        for rel in space.IsDefinedBy:
            if rel.is_a('IfcRelDefinesByProperties'):
                pset = rel.RelatingPropertyDefinition
                if pset.is_a('IfcPropertySet'):
                    print(f"    PSet: {pset.Name}")
                    for prop in pset.HasProperties:
                        print(f"      {prop.Name}: {prop.NominalValue if hasattr(prop, 'NominalValue') else 'N/A'}")

# Check if model 141 has different Space Usage.csv
path_141 = '/home/sffc348/Repos/cobbie/acc/bim_models/141/arc.ifc'
model_dir_141 = os.path.dirname(path_141)
csv_path_141 = os.path.join(model_dir_141, 'Space Usage.csv')
if os.path.exists(csv_path_141):
